-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.email_log(p_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, kind text, subject text, status text, error text, created_at timestamp with time zone, recipient_email text, recipient_name text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select l.id, l.kind, l.subject, l.status, l.error, l.created_at,
         l.recipient_email, p.name
  from public.email_send_log l
  left join public.profiles p on p.id = l.recipient_id
  where public.is_admin()
  order by l.created_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 500));
$function$;
